-- 1. Strea,ing services (fixed list, keys set manually)
CREATE TABLE IF NOT EXISTS core.dim_service (
    service_key SMALLINT PRIMARY KEY,
    service_name TEXT NOT NULL UNIQUE
);

-- 2. Devices (keys generated by the databese)
CREATE TABLE IF NOT EXISTS core.dim_device (
    device_key SMALLINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    device_name TEXT NOT NULL UNIQUE

);

-- 3. Hours of the day
CREATE TABLE IF NOT EXISTS core.dim_time (
    hour_key SMALLINT PRIMARY KEY CHECK (hour_key BETWEEN 0 AND 23),
    part_of_day TEXT NOT NULL
                CHECK (part_of_day IN ('night', 'morning', 'afternoon', 'evening'))
);

-- 4. Calendar (one row per day)
CREATE TABLE IF NOT EXISTS core.dim_date (
    date_key      INTEGER PRIMARY KEY,          -- YYYYMMDD, e.g. 20260315
    full_date     DATE NOT NULL UNIQUE,
    year          SMALLINT NOT NULL,
    quarter       SMALLINT NOT NULL CHECK (quarter BETWEEN 1 AND 4),
    month         SMALLINT NOT NULL CHECK (month BETWEEN 1 AND 12),
    month_name    TEXT NOT NULL,
    iso_week      SMALLINT NOT NULL CHECK (iso_week BETWEEN 1 AND 53),
    day_of_week   SMALLINT NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),  -- ISO: 1 = Monday
    day_name      TEXT NOT NULL,
    is_weekend    BOOLEAN NOT NULL
);

-- 5. Artists
CREATE TABLE IF NOT EXISTS core.dim_artist (
    artist_key INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    artist_name TEXT NOT NULL,
    artist_name_normalized TEXT NOT NULL UNIQUE, -- lowercase + trimmed, for matching
    country TEXT -- from MusicBrainz later, can be NULL if unknown 
);

-- 6. Tracks
CREATE TABLE IF NOT EXISTS core.dim_track (
    track_key INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    artist_key INTEGER NOT NULL,
    track_name TEXT NOT NULL,
    track_name_normalized TEXT NOT NULL,
    album_name TEXT NOT NULL DEFAULT 'Unknown',
    CONSTRAINT fk_dim_track_artist
    FOREIGN KEY (artist_key) REFERENCES core.dim_artist (artist_key),
    CONSTRAINT uq_dim_track_artist_track
        UNIQUE (artist_key, track_name_normalized)
);